/* default filament theme */
@import 'tailwindcss' source(none);
@import '/vendor/filament/filament/resources/css/index.css';

/* minimal theme */
@import '/vendor/filament/minimal-theme/resources/css/index.css';

@source '../../app/Filament/Resources/**/*.php';
@source '../../app/Filament/Admin/**/*.php';
@source '../../resources/views/filament/**/*.blade.php';
@source '../../resources/views/filament/admin/**/*.blade.php';
@source '../../vendor/filament/**/*.blade.php';
@source '../../resources/views/vendor/**/*.blade.php';

/* digital-hub package: src classes + blade views */
@source '../../src/**/*.php';
@source '../views/**/*.blade.php';

/* custom styles */
@import './digital-hub-custom.scss';

content.content:
packages/digital-hub/resources/theme/digital-hub-custom.scss
packages/digital-hub/resources/theme/digital-hub-theme.css
---

/**
 * =================================================================
 * General layout
 * =================================================================
 */


.fi-sidebar-header {
    @apply shadow-none!;
    border: 0;
    height: 4rem;
}

/* Su desktop Filament rende la sidebar trasparente, lasciando trasparire lo
   sfondo dell'area contenuto (vedi impostazione "Colore sfondo contenuto"). La
   forziamo bianca opaca SOLO in light mode, così la sidebar resta esclusa da
   quel colore. In dark mode si lascia lo sfondo di default del tema. */
.fi-sidebar:not(:where(.dark, .dark *)) {
    .fi-sidebar-nav {
        background-color: #FFF !important;
    }
}

.fi-sidebar-group .fi-sidebar-group-label {
    @apply font-medium uppercase text-black dark:text-gray-400 tracking-widest;
}

.fi-sidebar-item {

    &:not(.fi-active) {
        .fi-sidebar-item-icon {
            color: #000;
        }

        .fi-sidebar-item-label {
            color: #000;
        }
    }

}


/**
 * page header
 */
.fi-breadcrumbs-item-label {
    @apply text-black dark:text-gray-400 font-normal tracking-wide;
}
.fi-header-heading {
    @apply font-medium;
} 



/** overwrite sticky header font size, back to filament default **/
/* .fi-main.is-sticky .fi-header .fi-header-heading {
    @apply text-2xl  sm:text-3xl!;
}

.is-sticky.sticky-theme-default .fi-header:before {
    @apply border-black;
} */

/**
 * table
 */

 /* hide default ordering button, if not inside a modal (e.g. relation manager) */
.fi-ta-header-toolbar:not(.fi-modal-content *):not(.fi-resource-relation-manager *)
{
    button[wire\:click="toggleTableReordering"] {
        display: none;
    }
}


.fi-ta-table {
    thead{
        border-color: #000;
        border-top-width: 0;
    }

    .fi-ta-row{
        border-color: #000;
    }

    .fi-ta-header-cell {
        @apply font-medium tracking-wider text-black dark:text-gray-400 text-sm;
    }                                                                           

}
.fi-ta-header-toolbar {
    border-color: transparent;
}
.fi-ta-header-toolbar:not(.fi-modal-content *):not(.fi-resource-relation-manager *)


/**
 * =================================================================
 * END Layout
 * =================================================================
 */



/**
 * =================================================================
 * Components
 * =================================================================
 */
.fi-sc-section {
    @apply mb-0 mt-3 pt-0 pb-9;
}

.fi-sc-section:not(.no-border) {
    @apply  border-b border-gray-300 dark:border-white;
}
.fi-sc-section.no-border {
    @apply border-0;
}

.fi-section-header-heading {
    @apply text-xl pt-0 pb-4 font-semibold;

    &::before {
        content: '#'
    }
}

.fi-sc-actions {
    @apply mb-0 mt-2 pt-0 border-gray-300 dark:border-white;
}

.fi-btn.fi-outlined {
    background: #fff;
}
/**
 * =================================================================
 * END components
 * =================================================================
 */


/**
 * =================================================================
 * Login page
 * =================================================================
 */



.afh-login-wrapper {

    @apply p-12 shadow-xl  bg-white dark:bg-gray-800;

    .fi-logo {display: none;}


    .fi-simple-header-heading {
       @apply font-medium;
    }

    .fi-ac-btn-action {
        @apply py-3;
    }
}


/**
* =================================================================
* END Login page
* =================================================================
*/


/**
 * =================================================================
 * Form
 * =================================================================
 */

/**
 * Relation managers
 */
form ~ .fi-resource-relation-managers {
    margin-top: 5rem;
}

/**
 * Sticky actions
 */
.fi-sc-actions.fi-sticky .fi-ac {
    @apply bg-gray-100;
    bottom: 0 !important;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
}

/**
 * Helper text
 */
.fi-fo-field-wrp-helper-text {
    @apply text-xs italic;
}


.fi-fo-rich-editor-main {
    min-height: 200px;
}

.fi-section:not(.fi-aside) {
    background: transparent;
}

/**
 * =================================================================
 * END Form
 * =================================================================
 */


/**
 * =================================================================
 * Translation section
 * =================================================================
 */
/** hide the tab nav when there is only one locale **/
.digital-hub-translation-section.single-locale .fi-tabs.fi-contained {
    display: none !important;

    & + div {margin-top: 0;}
}

/**
 * =================================================================
 * END Translation section
 * =================================================================
 */

