 * General layout
 * =================================================================
 */


.fi-sidebar-header {
    @apply shadow-none!;
    border: 0;
    height: 4rem;
}

/* Su desktop Filament rende la sidebar trasparente, lasciando trasparire lo
   sfondo dell'area contenuto (vedi impostazione "Colore sfondo contenuto"). La
   forziamo bianca opaca SOLO in light mode, così la sidebar resta esclusa da
   quel colore. In dark mode si lascia lo sfondo di default del tema. */
.fi-sidebar:not(:where(.dark, .dark *)) {
    .fi-sidebar-nav {
        background-color: #FFF !important;
    }
}

.fi-sidebar-group .fi-sidebar-group-label {
    @apply font-medium uppercase text-black dark:text-gray-400 tracking-widest;
}

.fi-sidebar-item {

    &:not(.fi-active) {
        .fi-sidebar-item-icon {
            color: #000;
        }

        .fi-sidebar-item-label {
            color: #000;
        }
    }

}


/**
 * page header
 */
.fi-breadcrumbs-item-label {
    @apply text-black dark:text-gray-400 font-normal tracking-wide;
}
.fi-header-heading {
    @apply font-medium;
} 



